python3 - << 'PY'
import json,re
data=json.load(open("/tmp/type-map.json"))
sections=data["data"]["doc"]["sections"]
rows=[]
for s in sections:
    if s["id"]=="rules":
        continue
    for line in s["text"].splitlines():
        cells=[c.strip() for c in line.split("|")]
        if len(cells)<9 or not cells[1].startswith("`"):
            continue
        m=re.match(r'\A(\w[\w+]*) / (.+)\Z', cells[6])
        if not m:
            continue
        rows.append({
            "current": cells[1].strip("`"),
            "target": cells[2],
            "marker": cells[4],
            "action": m.group(1),
            "phase": m.group(2),
            "was": cells[7],
        })

print("=== was values distribution ===")
from collections import Counter
c=Counter(r["was"] for r in rows)
for k,v in sorted(c.items(), key=lambda x:-x[1]):
    print(f"{v:4} {k}")

print("\n=== published-ish (api/spi/(location)) with phase P2, any action ===")
for r in rows:
    was=r["was"]
    published = was.startswith("api") or was.startswith("spi") or "(location)" in was
    if "P2" in r["phase"] and published:
        print(f"{r['action']:12} {r['phase']:10} {was:20} {r['current']}")

print("\n=== close+move or relocate with published was any phase ===")
for r in rows:
    was=r["was"]
    published = was.startswith("api") or was.startswith("spi") or "(location)" in was
    if published and r["action"] in ("close+move","relocate","rename","move","retire","split"):
        if "P2" in r["phase"] or r["action"]=="close+move":
            print(f"{r['action']:12} {r['phase']:10} {was:20} {r['current']} -> {r['target'][:70]}")
